// Auto-generated favicon binary asset dictionary
export const FAVICON_DATA: Record<string, string> = {
  "head-128x128.ico": "",
  "head-16x16.ico": "",
  "head-24x24.ico": "",
  "head-256x256.ico": "",
  "head-32x32.ico": "",
  "head-48x48.ico": "",
  "head-64x64.ico": "",
  "icon-128x128.ico": "",
  "icon-16x16.ico": "",
  "icon-24x24.ico": "",
  "icon-256x256.ico": "",
  "icon-32x32.ico": "",
  "icon-48x48.ico": "",
  "icon-64x64.ico": ""
};

export function getFaviconBytes(filename: string): Uint8Array | null {
  const base64 = FAVICON_DATA[filename];
  if (!base64) return null;
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}
